import{_ as a,o as t,c as o,a0 as n}from"./chunks/framework.BXmxXpv-.js";const d=JSON.parse('{"title":"News","description":"Research news, publication announcements and laboratory updates from the Intelligent Computing Systems Laboratory at UESTC.","frontmatter":{"title":"News","description":"Research news, publication announcements and laboratory updates from the Intelligent Computing Systems Laboratory at UESTC.","outline":false,"aside":false},"headers":[],"relativePath":"news.md","filePath":"en/news.md","lastUpdated":1783607232000}'),r={name:"news.md"};function i(s,e,l,u,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="news" tabindex="-1">News <a class="header-anchor" href="#news" aria-label="Permalink to &quot;News&quot;">​</a></h1><h2 id="july-2026" tabindex="-1">July 2026 <a class="header-anchor" href="#july-2026" aria-label="Permalink to &quot;July 2026&quot;">​</a></h2><ul><li><p>Congratulations to our team on the acceptance of <strong><a href="/publication">Hades: A Hardware-Resident Substrate for Energy Admission in Intermittent Computing</a></strong> by <strong>MICRO 2026</strong>. This is the first MICRO paper from a university in Western China.</p></li><li><p>Congratulations to our team: <strong><a href="/publication">Speak and Be Known: Authenticating Users via Ear Canal Deformation on Earbuds</a></strong> was published in <strong>TMC 2026</strong>.</p></li></ul><h2 id="may-2026" tabindex="-1">May 2026 <a class="header-anchor" href="#may-2026" aria-label="Permalink to &quot;May 2026&quot;">​</a></h2><ul><li>Congratulations to our team on the acceptance of <strong><a href="/publication">μMan: Towards Device-Agnostic Power Management for Battery-free IoT</a></strong> by <strong>SenSys 2026</strong>.</li></ul><h2 id="march-2026" tabindex="-1">March 2026 <a class="header-anchor" href="#march-2026" aria-label="Permalink to &quot;March 2026&quot;">​</a></h2><ul><li>Congratulations to our team: <strong><a href="/publication">Remote Intermittency Control for RF-powered Devices via Backscatter Communication</a></strong> was published in <strong>TMC 2026</strong>.</li></ul><h2 id="december-2025" tabindex="-1">December 2025 <a class="header-anchor" href="#december-2025" aria-label="Permalink to &quot;December 2025&quot;">​</a></h2><ul><li><p>Congratulations to our team: <strong><a href="/publication">Bringing LoRa Downlink to Backscatter Devices</a></strong> was published in <strong>ToN 2025</strong>.</p></li><li><p>Congratulations to our team: <strong><a href="/publication">BlinkBud: Detecting Hazards from Behind via Sampled Monocular 3D Detection on a Single Earbud</a></strong> was published in <strong>IMWUT 2025</strong>.</p></li></ul><h2 id="november-2025" tabindex="-1">November 2025 <a class="header-anchor" href="#november-2025" aria-label="Permalink to &quot;November 2025&quot;">​</a></h2><ul><li>Congratulations to our team on the acceptance of <strong><a href="/publication">Hedgehog: Pushing the Range Limits of Ultrasonic Microphone Jammers</a></strong> by <strong>MobiCom 2025</strong>.</li></ul><h2 id="september-2025" tabindex="-1">September 2025 <a class="header-anchor" href="#september-2025" aria-label="Permalink to &quot;September 2025&quot;">​</a></h2><ul><li><p>Congratulations to Prof. Li Lu on being named a <strong>CCF Distinguished Member</strong>.</p></li><li><p><strong>Happy Teachers&#39; Day!</strong></p></li></ul><h2 id="july-2025" tabindex="-1">July 2025 <a class="header-anchor" href="#july-2025" aria-label="Permalink to &quot;July 2025&quot;">​</a></h2><ul><li><p>Congratulations to our team: <strong><a href="/publication">LoRaMirror: Illuminating Shadowed Spots in Urban LPWAN With Reflective Smart Surfaces</a></strong> was published in <strong>TMC 2025</strong>.</p></li><li><p>Congratulations to our team on the acceptance of <strong><a href="/publication">BaroAuth: Harnessing Ear Canal Deformation for Speaking User Authentication on Earbuds</a></strong> by <strong>ICDCS 2025</strong>.</p></li></ul><h2 id="june-2025" tabindex="-1">June 2025 <a class="header-anchor" href="#june-2025" aria-label="Permalink to &quot;June 2025&quot;">​</a></h2><ul><li>Congratulations to our team on the acceptance of <strong><a href="/publication">LEGO+: Redefining the Redundancy Removal for IoT Sensing Edge-End Systems</a></strong> by <strong>MobiSys 2025</strong>.</li></ul><h2 id="may-2025" tabindex="-1">May 2025 <a class="header-anchor" href="#may-2025" aria-label="Permalink to &quot;May 2025&quot;">​</a></h2><ul><li>Congratulations to our team: <strong><a href="/publication">Embedding Chips Over the Air: Rethink IoT Architecture for Ubiquitous Sensing</a></strong> was published in <strong>TMC 2025</strong>.</li></ul><h2 id="november-2024" tabindex="-1">November 2024 <a class="header-anchor" href="#november-2024" aria-label="Permalink to &quot;November 2024&quot;">​</a></h2><ul><li><p>Congratulations to our team on receiving the <strong>SenSys 2024 Best Paper Award</strong> for <strong><a href="/publication">Processor-Sharing Internet of Things Architecture for Large-scale Deployment</a></strong>. This is the first SenSys Best Paper awarded to a university in China.</p></li><li><p>Congratulations to our team on the acceptance of <strong><a href="/publication">Sisyphus: Redefining Low Power for LoRa Receiver</a></strong> by <strong>MobiCom 2024</strong>.</p></li></ul><h2 id="october-2024" tabindex="-1">October 2024 <a class="header-anchor" href="#october-2024" aria-label="Permalink to &quot;October 2024&quot;">​</a></h2><ul><li>The lab news page is now live. We will use this space to share major updates on research outcomes, project progress, student development, and academic activities.</li></ul>',23)])])}const m=a(r,[["render",i]]);export{d as __pageData,m as default};
